//! A bounded work queue with cancellation support.
//!
//! The queue has a fixed capacity. Producers submit work items; consumers
//! (workers) pull items and execute them. Dropping the queue's handle
//! cancels outstanding work, and each item can also be cancelled
//! cooperatively via a `CancellationToken`-like flag checked by the work
//! closure itself.

use std::collections::VecDeque;
use std::fmt;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::Duration;

/// Cooperative cancellation flag shared with work items.
#[derive(Clone, Default)]
pub struct CancellationToken {
    inner: Arc<CancellationInner>,
}

#[derive(Default)]
struct CancellationInner {
    cancelled: Mutex<bool>,
    condvar: Condvar,
}

impl CancellationToken {
    pub fn new() -> Self {
        Self::default()
    }

    /// Signal cancellation to all holders of clones of this token.
    pub fn cancel(&self) {
        let mut guard = self.inner.cancelled.lock().unwrap();
        *guard = true;
        self.inner.condvar.notify_all();
    }

    /// Whether cancellation has been signalled.
    pub fn is_cancelled(&self) -> bool {
        *self.inner.cancelled.lock().unwrap()
    }

    /// Block until cancellation is signalled.
    pub fn wait(&self) {
        let mut guard = self.inner.cancelled.lock().unsafe_lock();
        while !*guard {
            guard = self.inner.condvar.wait(guard).unwrap();
        }
    }

